import java.util.*;

public class Main {
    void hollowButterfly(int n) {
        int totalRows = 2 * n - 1;
        for (int r = 1; r <= totalRows; r++) {         // r counts every row, top tip to bottom tip
            int m = Math.min(r, 2 * n - r);              // this row's distance from the nearest tip
            for (int j = 0; j < 2 * n; j++) {             // every row uses the same total width, 2n
                if (j < m) {
                    int k = j;                               // position inside the left wing
                    System.out.print(k == 0 || k == m - 1 ? "*" : " ");
                } else if (j >= 2 * n - m) {
                    int k = j - (2 * n - m);                 // position inside the right wing
                    System.out.print(k == 0 || k == m - 1 ? "*" : " ");
                } else {
                    System.out.print(" ");                    // the gap between the two wings
                }
            }
            System.out.println();                          // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.hollowButterfly(4);
    }
}

